mapper.insert:
INSERT INTO tb_portfolio_shares (
    id, user_id, token_hash, included_credential_ids, included_badge_ids, expires_at, created_at
) VALUES (
    #{id}, #{userId}, #{tokenHash},
    CAST(#{credentialIds, jdbcType=ARRAY, typeHandler=org.apache.ibatis.type.ArrayTypeHandler} AS uuid[]),
    CAST(#{badgeIds, jdbcType=ARRAY, typeHandler=org.apache.ibatis.type.ArrayTypeHandler} AS uuid[]),
    #{expiresAt}, #{createdAt}
)

mapper.update:
UPDATE tb_portfolio_shares
   SET revoked_at = #{at}
 WHERE id = #{id} AND user_id = #{userId} AND revoked_at IS NULL

mapper.select:
UPDATE tb_portfolio_shares
   SET view_count = view_count + 1,
       last_viewed_at = #{at}
 WHERE token_hash = #{tokenHash}
   AND revoked_at IS NULL
   AND expires_at > #{at}
RETURNING

mapper.delete:
DELETE FROM tb_portfolio_shares
 WHERE (revoked_at IS NOT NULL AND revoked_at < #{threshold})
    OR expires_at < #{threshold}
